[DataContractAttribute]
public final class NDXSO99DataCollectContract implements SysOperationInitializable
{
    private TableId tableId;

}

Method.Source:
[DataMemberAttribute('TableId'), SysOperationControlVisibility(false)]
public TableId parmTableId(TableId _tableId = tableId)
{
    tableId = _tableId;
    return tableId;
}

public boolean tryAcquire()
{
    NDXSO99ParameterKey lNDXSO99ParameterKey = NDXSO99ParameterKey::find(tableId);

    if(!lNDXSO99ParameterKey)
    {
        lNDXSO99ParameterKey.Key = tableId;
        lNDXSO99ParameterKey.insert();
        return true;
    }

    return false;
}

public void release()
{
    NDXSO99ParameterKey lNDXSO99ParameterKey;

    delete_from lNDXSO99ParameterKey
        where lNDXSO99ParameterKey.Key == tableId;
}
